def _form():
    for no, ch in CH.items():
        lv = [it["lv"] for it in ch["items"]]
        assert lv.count("A") == 4 and lv.count("B") in (4, 5) and lv.count("C") == 2, lv
        for it in ch["items"]:
            for k in ("q", "a", "s", "tag"):
                assert it[k].strip(), (no, k)
            assert it["q"].count("$") % 2 == 0 and it["a"].count("$") % 2 == 0 and it["s"].count("$") % 2 == 0
            assert "<b>ポイント</b>" in it["s"]


def _sf(x, v, n):
    """x を有効数字 n 桁に丸めると v になることを確かめる"""
    assert float(f"{float(x):.{n}g}") == v, (float(x), v)


def verify():
    _form()
    R = Rational
    # A1
    assert 235 - 92 == 143 and 238 - 92 == 146
    assert (238 - 4, 92 - 2) == (234, 90) and (234, 90 + 1) == (234, 91)
    # A2
    x, y = symbols("x y")
    s = solve([Eq(232 - 4 * x, 208), Eq(90 - 2 * x + y, 82)], [x, y])
    assert s[x] == 6 and s[y] == 4
    # A3
    assert R(1, 2) ** (15 / R(5)) == R(1, 8) and R(1, 2) ** 5 == R(1, 32) and 5 * 5 == 25
    _sf(2 * 5.7e3, 1.1e4, 2)
    # B1
    dm = 2 * R(10073, 10000) + 2 * R(10087, 10000) - R(40015, 10000)
    assert dm == R(305, 10000)
    _sf(dm * R(166, 100) * 1e-27, 5.06e-29, 3); _sf(dm * 931, 28.4, 3); _sf(dm * 931 / 4, 7.10, 3)
    # B2
    dm2 = 2 * R(20136, 10000) - (R(30150, 10000) + R(10087, 10000))
    assert dm2 == R(35, 10000)
    Q = dm2 * 931
    _sf(Q, 3.3, 2); _sf(Q / 4, 0.81, 2); _sf(Q * 3 / 4, 2.4, 2)
    # 運動量保存：p 共通 → K ∝ 1/m
    p = symbols("p", positive=True)
    KHe, Kn = p ** 2 / (2 * 3), p ** 2 / (2 * 1)
    assert simplify(KHe / (KHe + Kn) - R(1, 4)) == 0
    # B3
    T = 8.0 * 24 * 3600
    lam = 0.693 / T
    _sf(T, 6.91e5, 3); _sf(lam, 1.0e-6, 2); _sf(lam * 1.0e15, 1.0e9, 2); _sf(lam * 1.0e15 / 8, 1.3e8, 2)
    _sf(1.0e15 * (1 - 1 / 8), 8.8e14, 2)
    # B4
    assert 235 + 1 - 141 - 3 == 92 and 92 - 56 == 36
    N = 1.0 / 235 * 6.0e23
    E = N * 200 * 1.6e-13
    _sf(N, 2.55e21, 3); _sf(E, 8.2e10, 2); _sf(E / 3.0e7, 2.7e3, 2); _sf(E / 9.0e16, 9.1e-7, 2)
    _sf(E / 9.0e16 / 1.0e-3 * 100, 0.09, 1)
    # B5
    _sf(4.87 * 222 / 226, 4.78, 3); _sf(4.87 * 4 / 226, 0.086, 2)
    # C1
    Q1 = 235 * (8.5 - 7.6)
    _sf(Q1, 2.1e2, 2)
    Q2 = 4 * 7.1 - (2 * 1.1 + 3 * 2.8)
    _sf(Q2, 17.8, 3); _sf(Q2 * 4 / 5, 14, 2); _sf(Q1 / 235, 0.90, 2); _sf(Q2 / 5, 3.6, 2)
    _sf((Q2 / 5) / (Q1 / 235), 4, 1)
    # C2
    m, A, v, v1, V1 = symbols("m A v v1 V1", positive=True)
    v1s, V1s = symbols("v1s V1s")
    s = solve([Eq(m * v, m * v1s + A * m * V1s), Eq(V1s - v1s, v)], [v1s, V1s])
    assert simplify(s[v1s] - (1 - A) / (1 + A) * v) == 0 and simplify(s[V1s] - 2 * v / (1 + A)) == 0
    # エネルギー保存の確認（弾性衝突）
    assert simplify(m * s[v1s] ** 2 / 2 + A * m * s[V1s] ** 2 / 2 - m * v ** 2 / 2) == 0
    f = lambda a: R(a - 1, a + 1) ** 2
    assert f(1) == 0 and f(12) == R(121, 169)
    _sf(f(12), 0.72, 2)
    lg = 2 * (1.041 - 1.114); rhs = 1 - 3 * 0.301 - 8
    assert abs(lg + 0.146) < 1e-12 and abs(rhs + 7.903) < 1e-12
    n_given = rhs / lg
    assert 54 < n_given < 55
    n_exact = _log10(0.025 / 2.0e6) / _log10(121 / 169)
    assert 54 < n_exact < 55
    assert f(12) ** 55 * 2.0e6 <= 0.025 < f(12) ** 54 * 2.0e6
